import{_ as d,o as r,a as e,b as a}from"./app.DKoEZOcr.js";const R=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"附录","link":"/api/appendix/appendix"},{"text":"Reg矢量计算接口指令单双发汇总","link":"/api/appendix/reg_vector_compute_interface_instruction_single_dual_issue_summary"}]},"headers":[],"relativePath":"api/appendix/reg_vector_compute_interface_instruction_single_dual_issue_summary.md","filePath":"api/appendix/reg_vector_compute_interface_instruction_single_dual_issue_summary.md","lastUpdated":1787050286000}'),V={name:"api/appendix/reg_vector_compute_interface_instruction_single_dual_issue_summary.md"};function s(i,t,n,S,l,o){return r(),e("div",null,[...t[0]||(t[0]=[a('<div><article class="markdown-body"><h1>Reg矢量计算接口指令单双发汇总<span id="reg-vector-dual-issue"></span></h1><p>本节汇总介绍了Reg矢量计算接口指令单双发的情况，指令单发指1个Cycle能够执行一条指令，指令双发指1个Cycle能够执行两条指令。 <br><strong>针对寄存器：1个Cycle只能写两个Reg寄存器；针对Unified Buffer（UB）：1个Cycle只能读两个VL（一个VL为256B），或者1个Cycle读一个VL和写一个VL。</strong></p><p>本节内容不包含软仿类接口，仅针对如下型号生效：</p><p>Ascend 950PR/Ascend 950DT</p><p><strong>表 1</strong> 接口指令双发汇总<a id="table-dual-issue"></a></p><table><thead><tr><th>接口类型</th><th>硬件指令名称</th><th>对应接口名称</th></tr></thead><tbody><tr><td>寄存器数据类型</td><td>PSET</td><td>CreateMask</td></tr><tr><td>寄存器数据类型</td><td>PLT</td><td>UpdateMask</td></tr><tr><td>Reg数据搬入</td><td>VLDS/VLD</td><td>连续对齐搬入（LoadAlign）：<br>单搬入模式（除了DIST_DS_B8、DIST_DS_B16分布模式）</td></tr><tr><td>Reg数据搬入</td><td>VLDAS/VLDA</td><td>连续非对齐搬入初始化（LoadUnAlignPre）</td></tr><tr><td>Reg数据搬入</td><td>VLDUS/VLDU</td><td>连续非对齐搬入（LoadUnAlign）</td></tr><tr><td>Reg数据搬入</td><td>PLDS/PLD</td><td>MaskReg搬入（LoadAlign）</td></tr><tr><td>Reg数据搬入</td><td>VMOV</td><td>Move（Reg数据搬入）</td></tr><tr><td>MaskReg计算</td><td>PMOV</td><td>Move（MaskReg计算）</td></tr><tr><td>MaskReg计算</td><td>PSEL</td><td>Select</td></tr><tr><td>MaskReg计算</td><td>MOVP</td><td>MoveMask</td></tr><tr><td>基础算术</td><td>VABS</td><td>Abs</td></tr><tr><td>基础算术</td><td>VEXP</td><td>Exp</td></tr><tr><td>基础算术</td><td>VSQRT</td><td>Sqrt</td></tr><tr><td>基础算术</td><td>VLN</td><td>Ln</td></tr><tr><td>基础算术</td><td>VLN</td><td>Log</td></tr><tr><td>基础算术</td><td>VNEG</td><td>Neg</td></tr><tr><td>基础算术</td><td>VRELU</td><td>Relu</td></tr><tr><td>基础算术</td><td>VPRELU</td><td>Prelu</td></tr><tr><td>基础算术</td><td>VLRELU</td><td>LeakyRelu</td></tr><tr><td>基础算术</td><td>VADD/VADDC</td><td>Add</td></tr><tr><td>基础算术</td><td>VADDCS</td><td>AddC</td></tr><tr><td>基础算术</td><td>VDIV</td><td>Div</td></tr><tr><td>基础算术</td><td>VMAX</td><td>Max</td></tr><tr><td>基础算术</td><td>VMIN</td><td>Min</td></tr><tr><td>基础算术</td><td>VMUL</td><td>Mul</td></tr><tr><td>基础算术</td><td>VMULL</td><td>Mull</td></tr><tr><td>基础算术</td><td>VSUB/VSUBC</td><td>Sub</td></tr><tr><td>基础算术</td><td>VSUBCS</td><td>SubC</td></tr><tr><td>基础算术</td><td>VADDS</td><td>Adds</td></tr><tr><td>基础算术</td><td>VMAXS</td><td>Maxs</td></tr><tr><td>基础算术</td><td>VMINS</td><td>Mins</td></tr><tr><td>基础算术</td><td>VMULS</td><td>Muls</td></tr><tr><td>逻辑计算</td><td>VNOT/PNOT</td><td>Not</td></tr><tr><td>逻辑计算</td><td>VAND/PAND</td><td>And</td></tr><tr><td>逻辑计算</td><td>VOR/POR</td><td>Or</td></tr><tr><td>逻辑计算</td><td>VXOR/PXOR</td><td>Xor</td></tr><tr><td>逻辑计算</td><td>VSHL</td><td>ShiftLeft</td></tr><tr><td>逻辑计算</td><td>VSHR</td><td>ShiftRight</td></tr><tr><td>逻辑计算</td><td>VSHLS</td><td>ShiftLefts</td></tr><tr><td>逻辑计算</td><td>VSHRS</td><td>ShiftRights</td></tr><tr><td>复合计算</td><td>VABSDIF</td><td>AbsSub</td></tr><tr><td>复合计算</td><td>VAXPY</td><td>Axpy</td></tr><tr><td>复合计算</td><td>VEXPDIF</td><td>ExpSub</td></tr><tr><td>复合计算</td><td>VMADD</td><td>MulDstAdd</td></tr><tr><td>复合计算</td><td>VMULA</td><td>MulAddDst</td></tr><tr><td>复合计算</td><td>VMULSCVT</td><td>MulsCast</td></tr><tr><td>比较与选择</td><td>VCMP</td><td>Compare</td></tr><tr><td>比较与选择</td><td>VCMPS</td><td>Compares</td></tr><tr><td>比较与选择</td><td>VSEL/PSEL</td><td>Select</td></tr><tr><td>类型转换</td><td>VCVTFI/VCVTFF/VCVTFF2/VCVTIF/VCVTII</td><td>Cast</td></tr><tr><td>类型转换</td><td>VTRC</td><td>Truncate</td></tr><tr><td>数据填充</td><td>VBR</td><td>Duplicate</td></tr><tr><td>索引操作</td><td>VCI</td><td>Arange</td></tr></tbody></table><p><strong>表 2</strong> 接口指令单发汇总<a id="table-single-issue"></a></p><table><thead><tr><th>接口类型</th><th>硬件指令名称</th><th>对应接口名称</th></tr></thead><tbody><tr><td>Reg数据搬入</td><td>VSLDB</td><td>非连续对齐搬入（LoadAlign）</td></tr><tr><td>Reg数据搬入</td><td>VLDS/VLD</td><td>连续对齐搬入（LoadAlign）：<br>双搬入模式和单搬入模式的DIST_DS_B8、DIST_DS_B16分布模式</td></tr><tr><td>Reg数据搬入</td><td>MOVVP</td><td>MaskGenWithRegTensor</td></tr><tr><td>Reg数据搬入</td><td>VGATHER2</td><td>Gather</td></tr><tr><td>Reg数据搬入</td><td>VGATHERB</td><td>GatherB</td></tr><tr><td>Reg数据搬出</td><td>VSSTB</td><td>非连续对齐搬出（StoreAlign）</td></tr><tr><td>Reg数据搬出</td><td>VSTS/VST</td><td>连续对齐搬出（StoreAlign）</td></tr><tr><td>Reg数据搬出</td><td>VSTUS/VSTU/VSTUR</td><td>连续非对齐搬出（StoreUnAlign）</td></tr><tr><td>Reg数据搬出</td><td>VSTAS/VSTA/VSTAR</td><td>连续非对齐搬出后处理（StoreUnAlignPost）</td></tr><tr><td>Reg数据搬出</td><td>PSTS/PST</td><td>MaskReg搬出（StoreAlign）</td></tr><tr><td>Reg数据搬出</td><td>PSTU</td><td>MaskReg非对齐搬出（StoreUnAlign）</td></tr><tr><td>Reg数据搬出</td><td>VSCATTER</td><td>Scatter</td></tr><tr><td>MaskReg计算</td><td>PINTLV</td><td>Interleave</td></tr><tr><td>MaskReg计算</td><td>PDINTLV</td><td>DeInterleave</td></tr><tr><td>MaskReg计算</td><td>PPACK</td><td>Pack</td></tr><tr><td>MaskReg计算</td><td>PUNPACK</td><td>UnPack</td></tr><tr><td>归约计算</td><td>VCADD</td><td>Reduce（ReduceType::SUM）</td></tr><tr><td>归约计算</td><td>VCMAX</td><td>Reduce（ReduceType::MAX）</td></tr><tr><td>归约计算</td><td>VCMIN</td><td>Reduce（ReduceType::MIN）</td></tr><tr><td>归约计算</td><td>VCGADD</td><td>ReduceDataBlock（ReduceType::SUM）</td></tr><tr><td>归约计算</td><td>VCCGMAX</td><td>ReduceDataBlock（ReduceType::MAX）</td></tr><tr><td>归约计算</td><td>VCGMIN</td><td>ReduceDataBlock（ReduceType::MIN）</td></tr><tr><td>归约计算</td><td>VCPADD</td><td>PairReduceElem</td></tr><tr><td>比较与选择</td><td>VSQZ</td><td>Squeeze</td></tr><tr><td>离散操作</td><td>VSELR</td><td>Gather</td></tr><tr><td>数据重排</td><td>VINTLV</td><td>Interleave</td></tr><tr><td>数据重排</td><td>VDINTLV</td><td>DeInterleave</td></tr><tr><td>数据压缩</td><td>VUSQZ</td><td>Unsqueeze</td></tr><tr><td>数据压缩</td><td>VPACK</td><td>Pack</td></tr><tr><td>数据压缩</td><td>VUNPACK</td><td>UnPack</td></tr><tr><td>直方图计算</td><td>DHISTv2</td><td>Histograms</td></tr></tbody></table></article></div>',1)])])}const c=d(V,[["render",s]]);export{R as __pageData,c as default};
